from collections import defaultdict
import networkx as nx
from typing import Dict, List

def get_abstract_states(grid: List[List[int]]) -> Dict[int, int]:
    """
    This function takes a 2D grid representing the environment and returns a dictionary mapping original states to their corresponding abstract states.

    The grouping of states into clusters is done based on symmetries in state connectivity and their relation to the goal. 
    States are considered equivalent if the optimal actions and expected value from following the policy are effectively the same.
    """

    # Define possible actions
    actions = ['up', 'down', 'left', 'right']

    # Initialize graph for BFS
    G = nx.DiGraph()

    # Add nodes to the graph representing original states
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            state_id = (i, j)
            G.add_node(state_id)

    # Add edges to the graph representing possible actions between states
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            state_id = (i, j)
            for action in actions:
                new_i, new_j = get_new_position(i, j, action, grid)
                if 0 <= new_i < len(grid) and 0 <= new_j < len(grid[0]) and grid[new_i][new_j] != 'X':
                    new_state_id = (new_i, new_j)
                    G.add_edge(state_id, new_state_id, weight=1)

    # Perform BFS to get strongly connected components
    sccs = list(nx.strongly_connected_components(G))

    # Initialize dictionary mapping original states to abstract states
    state_to_abstract_state = defaultdict(lambda: None)

    # Map original states to their corresponding abstract states based on symmetry and action semantics
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != 'X':
                for scc in sccs:
                    if (i, j) in scc:
                        for state_id in scc:
                            state_to_abstract_state[state_id] = len(sccs)

    return dict(state_to_abstract_state)


def get_new_position(i: int, j: int, action: str, grid: List[List[int]]) -> (int, int):
    """
    This function calculates the new position based on the given action.
    """
    if action == 'up':
        return i - 1, j
    elif action == 'down':
        return i + 1, j
    elif action == 'left':
        return i, j - 1
    else:
        return i, j + 1


