    abstract_states = {}

    # Define the possible actions (up, down, left, right)
    actions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Perform BFS to get the optimal path from the start state to each goal state
    q = deque([(start, 0)])
